using Dahomey.Cbor;
using Dahomey.Cbor.Serialization.Converters;
using Dahomey.Cbor.Serialization.Converters.Mappings;
using SurrealDb.Net.Models;

namespace SurrealDb.Examples.TodoApi.Aot.Models;

/// <summary>
/// Registers the CBOR converters of the app models without reflection, so that they work under Native AOT.
/// </summary>
/// <remarks>
/// This is what a <c>CborSerializerContext</c> generated by Dahomey.Cbor would register.
/// The generator cannot handle a model that derives from <see cref="Record"/> yet:
/// it does not support <c>[CborIgnoreIfDefault]</c> on <see cref="Record.Id"/>,
/// and it cannot use the <see cref="RecordId"/> converter that SurrealDb.Net registers.
/// Until it can, write the registrations by hand, as below.
/// </remarks>
internal static class AppCborMappings
{
    public static void Configure(CborOptions options)
    {
        var converters = options.Registry.ConverterRegistry;

        // A converter resolves the converters of its members when it is constructed,
        // so register the converter of each member type first.
        converters.RegisterConverter(typeof(DateOnly?), new NullableConverter<DateOnly>(options));

        options.Registry.ObjectMappingRegistry.Register<Todo>(objectMapping =>
            objectMapping.SetMemberMappings(
                [
                    // Same as the attributes on Record.Id: written as "id", and omitted when null
                    new DelegateMemberMapping<Todo, RecordId?>(
                        converters,
                        todo => todo.Id,
                        (todo, value) => todo.Id = value
                    )
                        .SetMemberName("id")
                        .SetIgnoreIfDefault(true),
                    new DelegateMemberMapping<Todo, string?>(
                        converters,
                        todo => todo.Title,
                        (todo, value) => todo.Title = value
                    ).SetMemberName(nameof(Todo.Title)),
                    new DelegateMemberMapping<Todo, DateOnly?>(
                        converters,
                        todo => todo.DueBy,
                        (todo, value) => todo.DueBy = value
                    ).SetMemberName(nameof(Todo.DueBy)),
                    new DelegateMemberMapping<Todo, bool>(
                        converters,
                        todo => todo.IsComplete,
                        (todo, value) => todo.IsComplete = value
                    ).SetMemberName(nameof(Todo.IsComplete)),
                ]
            )
        );

        converters.RegisterConverter(
            typeof(Todo),
            new ObjectConverter<Todo>(options, static () => new Todo())
        );
    }
}
